/**
 * EzyCore Ai - Apps Script Connector
 * Minimal bridge for communication between Blogger SPA and Google Apps Script.
 */

(function () {
    // 1. Initialize global Apps Script URL from LocalStorage
    const getStoredConfig = () => {
        try {
            const config = JSON.parse(localStorage.getItem('EzycoreConfig') || '{}');
            return config.webappUrl || '';
        } catch (e) {
            return '';
        }
    };

    window.appsScriptUrl = getStoredConfig();

    /**
     * Global function to send data to Google Apps Script Web App
     * @param {string} action - The action identifier (e.g., 'signin', 'signup', 'check_connection')
     * @param {object} data - The payload to send
     * @param {function} callback - Success handler
     * @param {function} errorCallback - Error handler
     * @param {string} overrideUrl - Optional URL to use instead of the configured one
     */
    window.sendDataToGoogle = function (action, data, callback, errorCallback, overrideUrl) {
        const targetUrl = overrideUrl || window.appsScriptUrl;

        if (!targetUrl || !targetUrl.startsWith('http')) {
            console.warn('[EzyCore] Invalid or missing Apps Script URL.');
            if (errorCallback) errorCallback('URL_MISSING');
            return;
        }

        // Construct payload with action
        const payload = {
            action: action,
            ...data
        };

        fetch(targetUrl, {
            method: 'POST',
            // Use text/plain to avoid pre-flight OPTIONS request (common for GAS)
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        })
            .then(response => {
                if (!response.ok) throw new Error('Network response was not ok');
                return response.json();
            })
            .then(json => {
                if (callback) callback(json);
            })
            .catch(err => {
                console.error('[EzyCore] GAS Request Failed:', err);
                if (errorCallback) errorCallback(err);
            });
    };
})();